function OverseaManageCafeCattyUpgradePopup:RefreshUI()
    MaidCoffeeUtils.PlayMusicById(MaidCoffeeConstants.MaidCoffeeMusicName.CattyLevelUpPop)
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local curLevel = component:GetMaidCoffeeLevel()
    local curStar = component:GetMaidCoffeeCattyStarLevel()  --初始为0级  要取下一等级的对应等级
    local starVo = MaidCoffeeUtils.GetMaidCoffeeStarUpVo(curStar + 1)
    local maxLevel = nil
    if starVo then
        maxLevel = starVo.rankid
    end
    if maxLevel then
        CfUtils.FillText(self.TxtLVNumber1,string.format("%s<size=40><color=#9d9d9d>/%s",curLevel - 1,maxLevel))
        CfUtils.FillText(self.TxtLVNumber2,string.format("%s<size=40><color=#9d9d9d>/%s",curLevel, maxLevel))
    end
    local vos = MaidCoffeeMgr:GetInstance():GetMaidCoffeeLockVosByLevel(curLevel - 1)
    local str = ""
    for i = 1, #vos do
        str = table.concat({str,vos[i].desc,"\n"})
    end
    CfUtils.FillText(self.TxtState,str)
end

